import json
import sys
from pathlib import Path

from src.greeting import greeting


def main() -> None:
    audience = json.loads(Path("config/app.json").read_text())["audience"]
    msg = greeting(audience)
    if "--json" in sys.argv[1:]:
        print(json.dumps({"greeting": msg}))
    else:
        print(msg)


if __name__ == "__main__":
    main()
